norm as (select s.*, upper(regexp_replace(s.unit,'[^A-Za-z0-9]','','g')) u from s),
j as (select id, so_no, room_no, project_id, revenue_ex_vat, revenue_inc_vat, working_status, cost,
             upper(regexp_replace(coalesce(room_no,''),'[^A-Za-z0-9]','','g')) u
      from jobs)
select count(*) total,
  count(*) filter (where m.id is not null) matched_so_room,
  count(*) filter (where m.id is null) unmatched
from norm n left join lateral (
  select j.* from j where j.so_no = n.so and j.u = n.u limit 1) m on true;